 if(!$id){q('INSERT INTO packages(branch_id,name,description,regular_price,package_price,validity_days,status,created_at) VALUES(?,?,?,?,?,?,?,NOW())',array_merge([$bid],$data));$id=(int)db()->lastInsertId();audit('create','packages',$id);} else {q('UPDATE packages SET name=?,description=?,regular_price=?,package_price=?,validity_days=?,status=? WHERE id=? AND branch_id=?',array_merge($data,[$id,$bid]));q('DELETE FROM package_services WHERE package_id=?',[$id]);audit('update','packages',$id);} foreach($_POST['service_id']??[] as $sid){$sid=(int)$sid;$qty=(int)($_POST['qty_'.$sid]??1); if($sid)q('INSERT INTO package_services(package_id,service_id,quantity) VALUES(?,?,?)',[$id,$sid,max(1,$qty)]);} flash('success','Package saved.'); redirect('modules/packages.php');}
